[Form]
public class MobParameters extends FormRun
{
    InventLocationId			inventLocationId;

    [FormObservable]
    str                 versionStr = '';
    [FormObservable]
    str                 publisher = '';
    [FormObservable]
    str                 versionName = '';
}

public void init()
{
    MobVersion versionClass = MobVersion::Construct();
    versionStr = versionClass.getModelVersion();
    publisher = versionClass.getModelPublisher();
    versionName = versionClass.getVersionName();
    super();
    MobParameters::find();
    this.UpdateOverwrites();
}

/// <summary>
///
/// </summary>
public void run()
{
    super();
    MobVersion::Construct().populateGroupWithExtensions(AddOnsGroup);
}

void setPickReceive(boolean checked)
{
    Mobpick.allowEdit(checked);
    Mobreceive.allowEdit(checked);
}

void UpdateOverwrites()
{
    this.setPickReceive(pickReceiveTypes.OverwriteDefault);
    UnderDeliveryValidation.enabled( MobParameters.PickProd );

}

/// <summary>
///
/// </summary>
public display Description modelVersion()
{
    return versionStr;
}

public display Name modelPublisher()
{

    return publisher;
}

public display Name modelVersionName()
{
    return versionName;
}

public void modified()
{
    super();
    if (MobParameters.PickPickingRoute)
    {
        MobParameters.PickSale = NoYes::No;
    }
}

public void modified()
{
    super();
    UnderDeliveryValidation.enabled( MobParameters.PickProd );
}

public void modified()
{
    super();
    if (MobParameters.PickSale)
    {
        MobParameters.PickPickingRoute = NoYes::No;
    }
}

public void modified()
{
    super();
    if (MobParameters.ReceiveArrival)
    {
        MobParameters.ReceivePurch = NoYes::No;
    }
}

public void modified()
{
    super();
    if (MobParameters.ReceivePurch)
    {
        MobParameters.ReceiveArrival = NoYes::No;
    }
}

public void modified()
{
    super();
    if (pickReceiveTypes.PickPickingRoute)
    {
        pickReceiveTypes.PickSale = NoYes::No;
    }
}

public void modified()
{
    super();
    if (pickReceiveTypes.PickSale)
    {
        pickReceiveTypes.PickPickingRoute = NoYes::No;
    }
}

public void modified()
{
    super();
    if (pickReceiveTypes.ReceiveArrival)
    {
        pickReceiveTypes.ReceivePurch = NoYes::No;
    }
}

public void modified()
{
    super();
    if (pickReceiveTypes.ReceivePurch)
    {
        pickReceiveTypes.ReceiveArrival = NoYes::No;
    }
}

display NoYes hasConfig(InventLocation invLoc)
{
    return MobInventLocationsPickReceiveTypes::find( invLoc.InventLocationId).RecId  != 0;
}

public int active()
{
    int ret;
    ret = super();
    element.UpdateOverwrites();
    return ret;
}

/// <summary>
///
/// </summary>
public void init()
{
    QueryBuildDataSource inventLocationQueryBuilder;
    super();

    inventLocationQueryBuilder = this.query().dataSourceTable(tableNum(InventLocation));
    inventLocationQueryBuilder.addRange(fieldnum(InventLocation, WHSEnabled)).value(queryValue(NoYes::No));
}

/// <summary>
///
/// </summary>
/// <param name = "_OldItem"></param>
/// <param name = "_NewItem"></param>
/// <param name = "_how"></param>
public void selectionChanged(FormTreeItem _OldItem, FormTreeItem _NewItem, FormTreeSelect _how)
{
    super(_OldItem, _NewItem, _how);
}

/// <summary>
/// ghosts og un-ghosts all checkboxes acroding to the value in OverVrite_OverWriteDefaults
/// </summary>
/// <remarks>
///
/// </remarks>

public void enter()
{
    super();
    element.UpdateOverwrites();
}

public void clicked()
{
    super();
    element.setPickReceive(this.checked());
}
